component.schema:
{
 "description": "InfisicalDynamicSecret is the Schema for the infisicaldynamicsecrets API.",
 "properties": {
  "spec": {
   "description": "InfisicalDynamicSecretSpec defines the desired state of InfisicalDynamicSecret.",
   "properties": {
    "authentication": {
     "properties": {
      "awsIamAuth": {
       "properties": {
        "identityId": {
         "type": "string"
        }
       },
       "required": [
        "identityId"
       ],
       "type": "object"
      },
      "azureAuth": {
       "properties": {
        "identityId": {
         "type": "string"
        },
        "resource": {
         "type": "string"
        }
       },
       "required": [
        "identityId"
       ],
       "type": "object"
      },
      "gcpIamAuth": {
       "properties": {
        "identityId": {
         "type": "string"
        },
        "serviceAccountKeyFilePath": {
         "type": "string"
        }
       },
       "required": [
        "identityId",
        "serviceAccountKeyFilePath"
       ],
       "type": "object"
      },
      "gcpIdTokenAuth": {
       "properties": {
        "identityId": {
         "type": "string"
        }
       },
       "required": [
        "identityId"
       ],
       "type": "object"
      },
      "kubernetesAuth": {
       "properties": {
        "autoCreateServiceAccountToken": {
         "description": "Optionally automatically create a service account token for the configured service account.\nIf this is set to `true`, the operator will automatically create a service account token for the configured service account. This field is recommended in most cases.",
         "type": "boolean"
        },
        "identityId": {
         "type": "string"
        },
        "serviceAccountRef": {
         "properties": {
          "name": {
           "type": "string"
          },
          "namespace": {
           "type": "string"
          }
         },
         "required": [
          "name",
          "namespace"
         ],
         "type": "object"
        },
        "serviceAccountTokenAudiences": {
         "description": "The audiences to use for the service account token. This is only relevant if `autoCreateServiceAccountToken` is true.",
         "items": {
          "type": "string"
         },
         "type": "array"
        }
       },
       "required": [
        "identityId",
        "serviceAccountRef"
       ],
       "type": "object"
      },
      "ldapAuth": {
       "properties": {
        "credentialsRef": {
         "properties": {
          "secretName": {
           "description": "The name of the Kubernetes Secret",
           "type": "string"
          },
          "secretNamespace": {
           "description": "The name space where the Kubernetes Secret is located",
           "type": "string"
          }
         },
         "required": [
          "secretName",
          "secretNamespace"
         ],
         "type": "object"
        },
        "identityId": {
         "type": "string"
        }
       },
       "required": [
        "credentialsRef",
        "identityId"
       ],
       "type": "object"
      },
      "universalAuth": {
       "properties": {
        "credentialsRef": {
         "properties": {
          "secretName": {
           "description": "The name of the Kubernetes Secret",
           "type": "string"
          },
          "secretNamespace": {
           "description": "The name space where the Kubernetes Secret is located",
           "type": "string"
          }
         },
         "required": [
          "secretName",
          "secretNamespace"
         ],
         "type": "object"
        }
       },
       "required": [
        "credentialsRef"
       ],
       "type": "object"
      }
     },
     "type": "object"
    },
    "dynamicSecret": {
     "properties": {
      "environmentSlug": {
       "type": "string"
      },
      "projectId": {
       "type": "string"
      },
      "projectSlug": {
       "type": "string"
      },
      "secretName": {
       "type": "string"
      },
      "secretsPath": {
       "type": "string"
      }
     },
     "required": [
      "environmentSlug",
      "secretName",
      "secretsPath"
     ],
     "type": "object"
    },
    "hostAPI": {
     "type": "string"
    },
    "leaseRevocationPolicy": {
     "type": "string"
    },
    "leaseTTL": {
     "type": "string"
    },
    "managedSecretReference": {
     "properties": {
      "creationPolicy": {
       "default": "Orphan",
       "description": "The Kubernetes Secret creation policy.\nEnum with values: 'Owner', 'Orphan'.\nOwner creates the secret and sets .metadata.ownerReferences of the InfisicalSecret CRD that created it.\nOrphan will not set the secret owner. This will result in the secret being orphaned and not deleted when the resource is deleted.",
       "type": "string"
      },
      "secretName": {
       "description": "The name of the Kubernetes Secret",
       "type": "string"
      },
      "secretNamespace": {
       "description": "The name space where the Kubernetes Secret is located",
       "type": "string"
      },
      "secretType": {
       "default": "Opaque",
       "description": "The Kubernetes Secret type (experimental feature). More info: https://kubernetes.io/docs/concepts/configuration/secret/#secret-types",
       "type": "string"
      },
      "template": {
       "description": "The template to transform the secret data",
       "properties": {
        "data": {
         "additionalProperties": {
          "type": "string"
         },
         "description": "The template key values",
         "type": "object"
        },
        "includeAllSecrets": {
         "description": "This injects all retrieved secrets into the top level of your template.\nSecrets defined in the template will take precedence over the injected ones.",
         "type": "boolean"
        },
        "metadata": {
         "description": "Custom metadata (labels/annotations) for the managed secret.\nWhen specified, these values are used instead of copying metadata from the InfisicalSecret CR.",
         "properties": {
          "annotations": {
           "additionalProperties": {
            "type": "string"
           },
           "description": "Custom annotations to apply to the managed secret",
           "type": "object"
          },
          "labels": {
           "additionalProperties": {
            "type": "string"
           },
           "description": "Custom labels to apply to the managed secret",
           "type": "object"
          }
         },
         "type": "object"
        }
       },
       "type": "object"
      }
     },
     "required": [
      "secretName",
      "secretNamespace"
     ],
     "type": "object"
    },
    "tls": {
     "properties": {
      "caRef": {
       "description": "Reference to secret containing CA cert",
       "properties": {
        "key": {
         "description": "The name of the secret property with the CA certificate value",
         "type": "string"
        },
        "secretName": {
         "description": "The name of the Kubernetes Secret",
         "type": "string"
        },
        "secretNamespace": {
         "description": "The namespace where the Kubernetes Secret is located",
         "type": "string"
        }
       },
       "required": [
        "key",
        "secretName",
        "secretNamespace"
       ],
       "type": "object"
      }
     },
     "type": "object"
    }
   },
   "required": [
    "authentication",
    "dynamicSecret",
    "leaseRevocationPolicy",
    "leaseTTL",
    "managedSecretReference"
   ],
   "type": "object"
  }
 },
 "title": "Infisical Dynamic Secret",
 "type": "object"
}
